function barRows(items){const max=Math.max(1,...items.map(x=>Number(x[1]||0)));return items.map(x=>'<div class="bar-row"><span>'+esc(x[0])+'</span><div class="bar-track"><i style="width:'+Math.round(Number(x[1]||0)/max*100)+'%;background:'+x[2]+'"></i></div><b>'+num(x[1])+'</b></div>').join('')||'<div class="empty">No data</div>'}
function renderInfographics(s){const l=s.live||{},c=s.content||{},queue=s.queue||{},total=(l.commandOk||0)+(l.commandFail||0),okPct=total?Math.round(l.commandOk/total*100):100;const mix=[['Courses',c.coursesToday||0,'#1b9c50'],['News',c.newsToday||0,'#2e72e7'],['GitHub',c.githubToday||0,'#7240ca'],['Movies',c.movieSearchesToday||0,'#ec9615']];if(q('#pulseInfo'))q('#pulseInfo').innerHTML='<article class="card info-card"><div class="head"><h3>Command outcome</h3><span class="tiny">Today</span></div><div class="donut-wrap"><div class="donut" style="--ok:'+okPct+'%"><b>'+okPct+'%</b></div><div class="bar-rows"><div class="priority"><span><i style="background:#1b9c50"></i>Successful</span><b>'+num(l.commandOk)+'</b></div><div class="priority"><span><i style="background:#e34d60"></i>Failed</span><b>'+num(l.commandFail)+'</b></div><div class="priority"><span><i style="background:#ec9615"></i>Queue depth</span><b>'+num(queue.pending)+'</b></div></div></div></article><article class="card info-card"><div class="head"><h3>Content mix</h3><span class="tiny">Published today</span></div><div class="bar-rows">'+barRows(mix)+'</div></article><article class="card info-card"><div class="head"><h3>Worker load</h3><span class="tiny">Live</span></div><div class="bar-rows">'+barRows([['Chats',queue.chats||0,'#2e72e7'],['Processing',queue.processing||0,'#7240ca'],['Movie slots',s.movieConcurrency?.active||0,'#ec9615']])+'</div></article>';if(q('#contentMix'))q('#contentMix').innerHTML=barRows(mix);if(q('#commandInfo'))q('#commandInfo').innerHTML='<article class="card info-card"><div class="head"><h3>Success ring</h3></div><div class="donut-wrap"><div class="donut" style="--ok:'+okPct+'%"><b>'+okPct+'%</b></div><p class="tiny" style="margin:0">'+num(l.commandOk)+' ok · '+num(l.commandFail)+' fail · avg '+num(l.avgLatencyMs)+' ms</p></div></article><article class="card info-card"><div class="head"><h3>Top commands</h3></div><div class="bar-rows">'+barRows((l.commandsToday||[]).slice(0,5).map(x=>['/'+x.cmd,x.count,'#1b9c50']))+'</div></article><article class="card info-card"><div class="head"><h3>Queue snapshot</h3></div><div class="bar-rows">'+barRows([['Waiting',queue.pending||0,'#ec9615'],['Processing',queue.processing||0,'#2e72e7'],['Movie wait',s.movieConcurrency?.waiting||0,'#e34d60']])+'</div></article>';const a=s.analytics||{};renderAnalytics(s,a)}
const num=n=>Number(n||0).toLocaleString(),time=v=>v?new Date(v).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'not run';
