function bindGroupControls(){q('#groupSearch')?.addEventListener('input',renderGroupBoard);q('#groupFeature')?.addEventListener('change',renderGroupBoard);q('#groupSort')?.addEventListener('change',renderGroupBoard);q('#groupReset')?.addEventListener('click',()=>{q('#groupSearch').value='';q('#groupFeature').value='';q('#groupSort').value='score';renderGroupBoard()});q('#showAllGroups')?.addEventListener('click',()=>{q('#groupSearch').value='';q('#groupFeature').value='';renderGroupBoard();q('#groupTable').closest('article').scrollIntoView({behavior:'smooth',block:'start'})})}
